(function () {
  try {
    /* main variables */
    var debug = 1;
    var variation_name = "cre-t-124";

    /* all Pure helper functions */

    function waitForElement(selector, trigger, delayInterval = 50, delayTimeout = 15000) {
      var interval = setInterval(function () {
        if (document && document.querySelector(selector) && document.querySelectorAll(selector).length > 0) {
          clearInterval(interval);
          trigger();
        }
      }, delayInterval);
      setTimeout(function () {
        clearInterval(interval);
      }, delayTimeout);
    }

    function addClass(selector, className) {
      var element = typeof selector === "string" ? document.querySelector(selector) : selector;
      if (!element) return;
      if (element.classList) element.classList.add(className);
      else if (!element.className.match(new RegExp("\b" + className + "\b"))) {
        element.className += " " + className;
      }
    }

    /* Variation functions */

    /* Variation Init */
    function init() {

      addClass('body', 'cre-t-124');

      const intervalId = setInterval(() => {

        const firstParagraph = document.querySelector('#intro-section .page-description .ct-span > p');
        if (firstParagraph) {
          firstParagraph.innerHTML = "Based on an independent review of 25 top providers. Covers your belongings and meets landlord requirements. Lowest prices guaranteed.";
          addClass(firstParagraph, 'cre-t-124-first-paragraph');
        }

        const listContainer = document.querySelector('.page-description span>ul');
        const logoHtml = `
        <div class="cre-t-124-logo-container">
          <div class="cre-t-124-info">
            We donate for every policy purchased
          </div>
          <div class="cre-t-124-all-logo">
            <img src="https://cdn-3.convertexperiments.com/uf/10007679/10007818/cre-124-all-logo-new-2_6a4607f8f14f1.png" alt="cre-124-all-logo">
          </div>
        </div>
      `;

        if (listContainer && !document.querySelector('.cre-t-124-logo-container')) {
          listContainer.insertAdjacentHTML('afterend', logoHtml);
        }

      }, 100);

      setTimeout(() => {
        clearInterval(intervalId);
      }, 5000);





    }

    /* Initialise variation */
    waitForElement("#intro-section .page-description .ct-span > p", init, 50, 15000);
  } catch (e) {
    if (debug) console.log(e, "error in Test " + variation_name);
  }
})();
